final class PlayerController {
    private var timer: Timer?

    func start() {
        // Timer holds the closure, self holds the timer.
        // [weak self] stops the closure from holding self.
        timer = Timer.scheduledTimer(withTimeInterval: 1, repeats: true) { [weak self] _ in
            guard let self else { return }
            self.tick()
        }
    }
    func tick() {}
    deinit { timer?.invalidate() }
}

protocol CartDelegate: AnyObject { func cartChanged() }
final class CartView {
    weak var delegate: CartDelegate?   // weak: the delegate usually owns us
}
